/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
class METDutyAdValorumClaimGenerateService extends METSysOperationService
{
    private METVendClaimProcessHelper              vendClaimProcessHelper;
    private METDutyAdValorumClaimGenerateContract  contract;
    private METVendClaimDutyRollVarTmp             vendClaimDutyRollVarTmp;
    private guid                                   topPickingProcessId;
    private List                                   itemList;
    private List                                   siteList;
    private boolean                                filterItemSite;
    private boolean                                generateClaim;

}

Method.Source:
/// <summary>
/// Returns name of the task service class.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METDutyAdValorumClaimGenerateTaskService);
}

/// <summary>
/// Returns name of the task service class method.
/// </summary>
/// <returns>Task service class method name</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METDutyAdValorumClaimGenerateTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:GenerateAdValorumClaim";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void processOperation(METDutyAdValorumClaimGenerateContract _contract)
{
    this.processInternal(_contract);
}

    /// <summary>
    /// Initialise global variables.
    /// </summary>
    public void initialise()
    {
        super();
        
        contract = dataContract as METDutyAdValorumClaimGenerateContract;

        if (generateClaim)
        {
            this.deleteDutyRollVariance();
            
            vendClaimProcessHelper = new METVendClaimProcessHelper();
            vendClaimProcessHelper.initParameters();
            vendClaimProcessHelper.initLedgerJournalParm();
            vendClaimProcessHelper.createLedgerJournalTable();
        }

        this.initVendClaimDutyRollVarTmp();
        this.stageDataIntoQueue();
    }

/// <summary>
/// Initializes table <c>METVendClaimDutyRollVarTmp</c> and sets its physical name in the contract.
/// Tasks/threads will use the physical name to reference this Tmp table.
/// </summary>
private void initVendClaimDutyRollVarTmp()
{
    select vendClaimDutyRollVarTmp;
    contract.parmVendClaimDutyRollVarTable(vendClaimDutyRollVarTmp.getPhysicalTableName());
}

    /// <summary>
    /// Stages data int table <c>METDutyRollMonthlyQueue</c>.
    /// </summary>
    void stageDataIntoQueue()
    {
        #OCCRetryCount

        METDutyRollVariance                    dutyRollVarianceGrouped;
        METDutyRollMonthlyQueue                queue;

        topPickingProcessId = newGuid();
        
        try
        {
            itemList = contract.parmItemList();
            siteList = contract.parmSiteList();
            filterItemSite = contract.parmFilterItemSite();
            generateClaim = contract.parmGenerateClaims();
            
            METDutyRollMonthlyQueue::cleanUpABNValidationJobQueue();

            if (filterItemSite)
            {
                if (!siteList.empty() && !itemList.empty())
                {
                    ListEnumerator iter = siteList.getEnumerator();

                    while (iter.moveNext())
                    {
                        InventSiteId siteId  = iter.current();
                        this.stageDataIntoQueueQueryFiltered(siteId);
                    }

                }
                else if (!itemList.empty())
                {
                    METDutyRollVariance  dutyRollVarianceGroupedSite;

                    while select Site from dutyRollVarianceGroupedSite
                        group by Site
                            where dutyRollVarianceGroupedSite.InventTransType == InventTransType::Purch
                               && dutyRollVarianceGroupedSite.ClaimCreated == NoYes::No
                    {
                        this.stageDataIntoQueueQueryFiltered(dutyRollVarianceGroupedSite.Site);
                    }
        
                }
                
            }
            else
            {
                insert_recordset queue (ProcessId, SiteId, ItemId)
                    select topPickingProcessId, Site, ItemId from dutyRollVarianceGrouped
                        group by Site, ItemId
                            where dutyRollVarianceGrouped.InventTransType == InventTransType::Purch
                               && dutyRollVarianceGrouped.ClaimCreated == NoYes::No;
                
            }

        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }

        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }

        }
        catch (Exception::Error)
        {
            exceptionTextFallThrough();
        }

    }

    // <summary>
    /// Stages <c>Query</c> filtered data into <c>METDutyRollMonthlyQueue</c>.
    /// </summary>
    /// <param name = "_query"> <c>Query</c>. </param>
    /// <param name = "_month"> months. </param>
    void stageDataIntoQueueQueryFiltered(InventSiteId _siteId)
    {
        METDutyRollMonthlyQueue queue;
        RecordInsertList        queueInsertList;

        ttsbegin;

        if (!itemList.empty())
        {
            queueInsertList = new RecordInsertList(tableNum(METDutyRollMonthlyQueue));
            ListEnumerator itemIter = itemList.getEnumerator();

            while (itemIter.moveNext())
            {
                ItemId itemId = itemIter.current();

                queue.clear();
                queue.ProcessId = topPickingProcessId;
                queue.ItemId = itemId;
                queue.SiteId = _siteId;
                queueInsertList.add(queue);
            }

            // Bulk insert all records at once
            queueInsertList.insertDatabase();
        }

        ttscommit;
    }

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METDutyAdValorumClaimGenerateContract();
}

    /// <summary>
    /// Waits for task(s) to finish.
    /// </summary>
    public void waitTaskFinished()
    {
        super();

        if (generateClaim)
        {
            this.generateVendClaims();
        }
    }

    /// <summary>
    /// Generate vendor claims.
    /// </summary>
    private void generateVendClaims()
    {
        METDutyRollVariance       dutyRollVariance;
   
        while select vendClaimDutyRollVarTmp
        {
            select firstonly dutyRollVariance
                where dutyRollVariance.RecId == vendClaimDutyRollVarTmp.DutyRollVarRecId;

            vendClaimProcessHelper.parmDutyRollVariance(dutyRollVariance);
            vendClaimProcessHelper.processForDutyVariance();

            if(dutyRollVariance)
            {
                ttsbegin;
                dutyRollVariance.selectForUpdate(true);
                dutyRollVariance.ClaimCreated = NoYes::Yes;
                dutyRollVariance.update();
                ttscommit;
            }
        }

        vendClaimProcessHelper.postLedgerJournal();               
    }

    /// <summary>
    /// Deletes duty roll variance records created before the current month.
    /// </summary>
    private void deleteDutyRollVariance()
    {
        METDutyRollVariance     dutyRollVariance;

        utcdatetime systemDateTime = DateTimeUtil::getSystemDateTime();
        utcdatetime dateTimeStartMth = DateTimeUtil::newDateTime(DateTimeUtil::date(DateTimeUtil::addDays(systemDateTime, 1 - DateTimeUtil::day(systemDateTime))), 0);
        
        ttsbegin;
        delete_from dutyRollVariance
            where dutyRollVariance.ClaimCreated == NoYes::Yes
               && dutyRollVariance.CreatedDateTime < dateTimeStartMth
               && dutyRollVariance.InventTransType == InventTransType::Purch;
        ttscommit;
    }
